package ama.transcript;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;
public final class Task11Fix01LedgerProbe {
 public static Map<String,Object> verify(JdbcPublicationService s,String meeting,String selected)throws Exception {
  var a=s.authority;var normal=s.limits;var ledger=normal.ledger(a.readBudget(),a.canonicalBudget(),()->false);var plan=PublicationGraph.discover(a.dataSource(),meeting,ledger);long[] metadata=ledger.usage();
  var row=plan.rows().get("publication_submission").stream().filter(r->selected.equals(r.get("task_id"))).findFirst().orElseThrow();var actor=new ama.contract.IdentityContracts.Actor((String)row.get("requester_id"),ama.contract.IdentityContracts.Status.ACTIVE,Set.of(ama.contract.IdentityContracts.Role.USER));
  String manifest=a.transactionRunner().required(()->{a.savedAccess().require(a.savedAccess().lock(actor,meeting),ama.access.MeetingAccess.Action.EDIT);s.j.queryForList("SELECT id FROM publication WHERE meeting_id=? ORDER BY id FOR UPDATE",meeting);s.j.queryForList("SELECT id FROM final_confirmation WHERE meeting_id=? ORDER BY id FOR UPDATE",meeting);PublicationGraph.lock(a.dataSource(),plan,true);PublicationGraph.lock(a.dataSource(),plan,false);return s.j.queryForObject("SELECT request_manifest FROM publication_submission WHERE task_id=?",String.class,selected);});var fields=ControlledKnowledgeClient.parse(manifest.getBytes(java.nio.charset.StandardCharsets.UTF_8),65536);
  long[] before=ledger.usage();PublicationManifest.history(fields,plan);long[] after=ledger.usage();assertTrue(after[0]>before[0]&&after[3]>before[3]&&after[5]>before[5],"Original manifest validation and history must consume the same operation ledger before allocation");
  var results=new LinkedHashMap<String,Object>();results.put("historyBefore",before);results.put("historyAfter",after);
  for(String dimension:List.of("maxFactRows","maxFactEdges")){
   var archive=replace(a.readBudget(),dimension,metadata[dimension.equals("maxFactRows")?5:6]*2+1);var cumulative=normal.ledger(archive,a.canonicalBudget(),()->false);PublicationGraph.discover(a.dataSource(),meeting,cumulative);PublicationGraph.discover(a.dataSource(),meeting,cumulative);assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationGraph.discover(a.dataSource(),meeting,cumulative)).code());results.put(dimension,cumulative.usage());
  }
  var sample=normal.ledger(a.readBudget(),a.canonicalBudget(),()->false);ControlledKnowledgeClient.canonical(fields,sample);long[] one=sample.usage();
  for(int dimension=0;dimension<5;dimension++){
   long[] limits={normal.utf8(),normal.scalars(),normal.utf16(),normal.copyBytes(),normal.copyUtf16()};limits[dimension]=one[dimension]*2+1;
   var constrained=new TranscriptAcquisitionBudget(limits[0],limits[1],limits[2],limits[3],limits[4],normal.responseBytes(),normal.revisionDepth(),normal.revisionNodes(),normal.tasks()).ledger(a.readBudget(),a.canonicalBudget(),()->false);ControlledKnowledgeClient.canonical(fields,constrained);ControlledKnowledgeClient.canonical(fields,constrained);assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,assertThrows(ama.contract.MinutesContracts.Failure.class,()->ControlledKnowledgeClient.canonical(fields,constrained)).code());results.put("canonicalDimension"+dimension,constrained.usage());
  }
  var remote=plan.rows().get("external_execution").stream().filter(e->e.get("marked_at")!=null&&"FAILED".equals(e.get("state"))&&plan.rows().get("publication_submission").stream().anyMatch(x->x.get("task_id").equals(e.get("task_id")))).findFirst().orElseThrow();var reference=new PublicationRecordedLookup.Reference((String)remote.get("operation_id"),(String)remote.get("id"),((Number)remote.get("execution_no")).longValue(),new ama.contract.TaskContracts.SubjectRef("MEETING",meeting));
  var measured=normal.ledger(a.readBudget(),a.canonicalBudget(),()->false);var identity=PublicationRecordedLookup.captureReplacement(s,reference,actor,(String)row.get("publication_id"),measured).identity();s.replacementProof(identity,reference.executionId(),reference.executionNo(),measured);long response=measured.usage()[7];assertTrue(response>0);
  var limited=new TranscriptAcquisitionBudget(normal.utf8(),normal.scalars(),normal.utf16(),normal.copyBytes(),normal.copyUtf16(),response*2,normal.revisionDepth(),normal.revisionNodes(),normal.tasks()).ledger(a.readBudget(),a.canonicalBudget(),()->false);var original=PublicationRecordedLookup.captureReplacement(s,reference,actor,(String)row.get("publication_id"),limited).identity();s.replacementProof(original,reference.executionId(),reference.executionNo(),limited);s.replacementProof(original,reference.executionId(),reference.executionNo(),limited);assertThrows(java.io.IOException.class,()->s.replacementProof(original,reference.executionId(),reference.executionNo(),limited));assertEquals(response*2,limited.usage()[7]);results.put("actualRepeatedReceiptResponse",Map.of("responseBytesEach",response,"usage",limited.usage(),"qualification","same actual original receipt fetched repeatedly on one ledger; no multiple distinct provider receipts claimed"));return results;
 }
 @SuppressWarnings("unchecked") private static <T> T replace(T record,String field,long value)throws Exception {var components=record.getClass().getRecordComponents();Class<?>[] types=new Class<?>[components.length];Object[] args=new Object[components.length];for(int i=0;i<components.length;i++){var c=components[i];types[i]=c.getType();args[i]=c.getAccessor().invoke(record);if(c.getName().equals(field)){if(c.getType()==int.class)args[i]=Math.toIntExact(value);else args[i]=value;}}return (T)record.getClass().getDeclaredConstructor(types).newInstance(args);}
}
